const extract = (dir) => {
  const made = [];
  for (const f of FILES) {
    const target = path.join(dir, f.p.split('/').join(path.sep));
    mkdirSync(path.dirname(target), { recursive: true });
    if (existsSync(target) && !FORCE) {
      console.error('✗ 目标已存在：' + target);
      console.error('  ⇒ 换个 --out 目录 ✓ 或确认要覆盖再加 --force ✗（默认不覆盖任何已有文件 ✓）');
      process.exit(2);
    }
    const buf = Buffer.from(f.b, 'base64');
    const h = crypto.createHash('sha256').update(buf).digest('hex');
    if (h !== f.h || buf.length !== f.n) {
      console.error('✗ 内嵌数据损坏：' + f.p + '（sha256 不符 ✗）⇒ 请重新下载这个单文件 ✓');
      process.exit(2);
    }
    writeFileSync(target, buf);
    made.push(f.p);
  }
  return made;
};

